            presentation.append(" - ");
            presentation.append(value);
        }
        return presentation.toString();
    }

    @Override
    public void focusGained(FocusEvent e) {
        setFormatterFactory(formatterFactory);
        setText(String.valueOf(getValue()));
        SwingUtilities.invokeLater(new Runnable() {
            @Override
            public void run() {
                selectAll();
            }
        });
    }

